list_shipping_classes.code:
const response = await client.shippingClasses.listShippingClasses({limit: 20});
for (const shippingClass of response.map.shipping_classes) {
    console.log(shippingClass.id, shippingClass.name, shippingClass.is_default);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_shipping_class.code:
const response = await client.shippingClasses.createShippingClass({
    shipping_class: {name: 'Bulky Goods', description: 'Items over 20kg'},
});
console.log(response.map.shipping_class.id, response.map.shipping_class.is_default);

get_shipping_class.code:
const response = await client.shippingClasses.getShippingClass(2);
const shippingClass = response.map.shipping_class;
console.log(shippingClass.name, shippingClass.description, shippingClass.is_default);

update_shipping_class.code:
const response = await client.shippingClasses.updateShippingClass(3, {
    shipping_class: {name: 'Bulky Goods', description: 'Items over 25kg'},
});
console.log(response.map.shipping_class.name, response.map.shipping_class.description);
